<script lang="ts">
 import type {HealthView} from '../generated/HealthView';
 import type {Driver} from '../generated/Driver';
 import type {Snippet} from 'svelte';
 import {masonry} from '../masonry';
 import Card from '../components/Card.svelte';
 import Icon from '../components/Icon.svelte';
 import Sparkline from '../components/Sparkline.svelte';
 // Health summarises: the long view first, then this morning's vitals, then each daily metric over a few
 // ranges with its usual band. Comparisons and all history live on each metric's detail.
 import RangeBar from '../components/RangeBar.svelte';
 import HistoryChart from '../components/HistoryChart.svelte';
 import VitalsMonitor from '../components/VitalsMonitor.svelte';
 import IntensityCard from '../components/IntensityCard.svelte';
 import {colors,toneColor} from '../charts';
 import {dateLabel,num} from '../format';
 import {fitnessAgeColor,driverScale,driverRange,driverTarget,driverGap} from '../fitness';
 import {trendBand,rangeName} from '../signals';
 let {healthData,navigate,toggleJournal,weightContent,journalBusy=false,journalOpen=$bindable(false),journalDayOpen=$bindable(null),historical=false}:{healthData:HealthView,navigate:(route:string)=>void,toggleJournal:(enabled:boolean)=>void,weightContent?:Snippet,journalBusy?:boolean,journalOpen?:boolean,journalDayOpen?:string|null,historical?:boolean}=$props();
 let age=$derived(healthData.fitnessAge);
 let hrv=$derived(healthData.vitals.readings.find(v=>v.kind==='hrv'));
 const driverDigits=(d:Driver)=>d.key==='bmi'||d.key==='vigorousDays'?1:0;
 // The bar runs 20–70, widened in tens to keep both marks on it; the split at your age is the colour change.
 const ageSpan=(...ages:number[])=>{const lo=Math.min(20,Math.floor((Math.min(...ages)-5)/10)*10),hi=Math.max(70,Math.ceil((Math.max(...ages)+5)/10)*10);return (v:number)=>(v-lo)/(hi-lo)*100};
</script>
<div class="dashboard health-dashboard" {@attach masonry}>
 <Card title="Fitness Age" help="fitness-age" id="fitness-age">{#snippet aside()}{#if age.change12m!=null && Math.abs(age.change12m)>=1}<span class="pill" style:color={age.change12m<0?colors.good:colors.poor}>{num(Math.abs(age.change12m))} {Math.round(Math.abs(age.change12m))===1?'yr':'yrs'} {age.change12m<0?'younger':'older'} than a year ago</span>{/if}{/snippet}<div class="age-hero"><div><div class="age-number n" style:color={age.fitnessAge!=null?fitnessAgeColor(age.fitnessAge,age.chronologicalAge):undefined}>{num(age.fitnessAge)}</div>{#if age.fitnessAge!=null && age.chronologicalAge!=null}<div class="age-caption">{#if age.fitnessAge>age.chronologicalAge}<b>{num(age.fitnessAge-age.chronologicalAge)} years older</b> than your age{:else}<b>{num(age.chronologicalAge-age.fitnessAge)} years younger</b> than your age{/if}</div>{/if}<div class="age-source">Garmin estimate{age.recordedOn?` · ${dateLabel(age.recordedOn)}`:''}</div></div></div>{#if age.fitnessAge!=null && age.chronologicalAge!=null}{@const span=ageSpan(age.fitnessAge,age.chronologicalAge)}<button class="agebar-open" aria-label={`Fitness Age ${num(age.fitnessAge)}, your age ${num(age.chronologicalAge)}. Open Fitness Age history`} onclick={()=>navigate('metric/fitnessAge')}><div class="agebar" style:--age-status={fitnessAgeColor(age.fitnessAge,age.chronologicalAge)} style:--age-split={span(age.chronologicalAge)+'%'}><div class="age-mark fit" style:left={span(age.fitnessAge)+'%'}><span>YOU {num(age.fitnessAge)}</span></div><div class="age-mark real" style:left={span(age.chronologicalAge)+'%'}><span>AGE {num(age.chronologicalAge)}</span></div></div></button>{/if}<button class="link-row history-more" onclick={()=>navigate('metric/fitnessAge')}>Fitness Age history<Icon name="chevron" size={15}/></button></Card>
 {#if healthData.drivers.length}<Card title="What sets it"><div class="drivers">{#each healthData.drivers as d}{@const lever=healthData.lever?.key===d.key?healthData.lever:null}<div class="driver" class:lever-driver={!!lever}><span>{d.name}{#if d.target!=null && d.met}<i style:color={toneColor(d.tone)}><Icon name="check" size={14}/>Met</i>{/if}</span><b class="n">{num(d.value,driverDigits(d))}<small>{d.unit}</small></b><div role="img" aria-label={`${d.name} ${num(d.value,driverDigits(d))} ${d.unit}${d.target!=null?`, ${driverTarget(d)}, ${d.met?'met':'not met'}`:''}`}><RangeBar value={d.value} scale={driverScale(d.key)} range={driverRange(d.key,d.target)} color={toneColor(d.tone)}/></div>{#if d.target!=null}<small class="driver-target">{driverTarget(d)}</small>{#if !d.met && d.value!=null}<small class="driver-gap" style:color={toneColor(d.tone)}>{driverGap(d)}</small>{/if}{/if}{#if lever?.ageIfMet!=null}<small class="driver-lever">Biggest lever · reach {num(lever.target,driverDigits(d))} for age {num(lever.ageIfMet,1)}</small>{/if}</div>{/each}</div></Card>{/if}
 {#if historical && healthData.detail.unavailable.includes('vitals')}<Card title="Vitals"><p class="small">Garmin has no vitals for this day.</p></Card>{:else}<VitalsMonitor vitals={healthData.vitals} date={healthData.date} open={(kind)=>navigate('metric/'+kind)}/>{/if}
 <Card title="Resting heart rate" extra="over-time" help="metric-range"><HistoryChart compact values={[]} endDate={healthData.date} label="Resting heart rate" unit="bpm" metric="restingHr" initialRange="days30" band={trendBand('restingHr',healthData)} bandLabel="Current Raring usual range" openDay={day=>navigate('metric/heartRate/'+day)} more={()=>navigate(historical?'metric/heartRate/'+healthData.date:'metric/heartRate')} moreLabel={historical?'Heart rate for this day and all history':'Heart rate today and all history'}/></Card>
 <Card title="Overnight HRV" extra="over-time"><HistoryChart compact values={[]} endDate={healthData.date} label="Overnight HRV" unit="ms" metric="hrv" initialRange="days30" band={trendBand('hrv',healthData)} bandLabel={hrv?'Current '+rangeName(hrv):undefined} more={()=>navigate('metric/hrv')}/></Card>
 <Card title="Average stress" extra="over-time"><HistoryChart compact values={[]} endDate={healthData.date} label="Average stress" metric="stress" initialRange="days30" openDay={day=>navigate('metric/stress/'+day)} more={()=>navigate(historical?'metric/stress/'+healthData.date:'metric/stress')} moreLabel={historical?'Stress for this day and all history':'Stress today and all history'}/>{#if healthData.detail.unavailable.includes('stress')}<p class="small">Garmin has no stress readings for this day.</p>{/if}</Card>
 <Card title="Body Battery · daily high" extra="over-time"><HistoryChart compact values={[]} endDate={healthData.date} label="Body Battery daily high" metric="bodyBattery" initialRange="days30" more={()=>navigate('metric/bodyBattery')} moreLabel="Body Battery today and all history"/></Card>
 {#if weightContent}{@render weightContent()}{:else if healthData.bodyWeight}{@const weight=healthData.bodyWeight}<Card title="Weight"><div class="age-small"><div><div class="big n">{num(weight.value,1)}<small>&nbsp;{weight.unit}</small></div><div class="small">Last measured {dateLabel(weight.measuredOn)}</div></div><Sparkline values={weight.trend} w={160} h={64} color={colors.neutral} fill={false} points/></div><p class="small">{#if weight.bodyFat!=null}Body fat {num(weight.bodyFat,1)}% ·&nbsp;{/if}{#if weight.bmi!=null}BMI {num(weight.bmi,1)} ·&nbsp;{/if}Last 12 weeks</p></Card>{/if}
 {#if healthData.intensity}<IntensityCard intensity={healthData.intensity} open={()=>navigate('plan')} id="intensity"/>{/if}
 <Card title="Garmin journal" extra="journal" id="journal"><p class="small">Your private lifestyle logs from Garmin · last 7 days.</p>{#if !healthData.journalEnabled}<button class="secondary" disabled={journalBusy} onclick={()=>void toggleJournal(true)}>Allow local journal reads</button><p class="small">Off by default. Garmin logs are fetched only after you allow them; turn off in Settings.</p>{:else if !journalOpen}<button class="secondary" onclick={()=>journalOpen=true}>Open journal</button>{:else}<button class="secondary" onclick={()=>journalOpen=false}>Close journal</button>{#each healthData.journal as day}<div class="journal-day"><b>{dateLabel(day.date)}</b><small>Garmin · {day.state==='empty'?'No entries recorded':day.state==='available'?'Recorded':day.state==='stale'?'May be out of date':day.state==='unavailable'?'Not available':'Not checked'}</small>{#each day.entries.slice(0,journalDayOpen===day.date?undefined:3) as entry}<div class="journal-entry"><span>{entry.name}</span><span>{entry.value??'Value unknown'}</span></div>{/each}{#if day.entries.length>3}<button class="journal-more" onclick={()=>journalDayOpen=journalDayOpen===day.date?null:day.date}>{journalDayOpen===day.date?'Show less':`Show ${day.entries.length-3} more`}</button>{/if}</div>{/each}{/if}</Card>

</div>
